function readJson<T>(path: string): T {
  return JSON.parse(readFileSync(path, 'utf8')) as T;
}

function readBoundedUtf8(path: string, maxBytes: number): { text: string; truncated: boolean } {
  const fd = openSync(path, 'r');
  try {
    const buffer = Buffer.allocUnsafe(maxBytes + 1);
    const bytesRead = readSync(fd, buffer, 0, buffer.length, 0);
    return {
      text: buffer.subarray(0, Math.min(bytesRead, maxBytes)).toString('utf8'),
      truncated: bytesRead > maxBytes,
    };
  } finally {
    closeSync(fd);
  }
}

function atomicWrite(path: string, value: unknown, mode = 0o600): void {
  const temp = `${path}.tmp-${process.pid}-${randomBytes(6).toString('hex')}`;
  writeFileSync(temp, `${canonicalJson(value)}\n`, { encoding: 'utf8', mode, flag: 'wx' });
  renameSync(temp, path);
  chmodSync(path, mode);
}

function writeExclusive(path: string, value: unknown, mode = 0o600): boolean {
  const temp = `${path}.tmp-${process.pid}-${randomBytes(6).toString('hex')}`;
  try {
    writeFileSync(temp, `${canonicalJson(value)}\n`, { encoding: 'utf8', mode, flag: 'wx' });
    chmodSync(temp, mode);
    linkSync(temp, path);
    return true;
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'EEXIST') return false;
    throw error;
  } finally {
    unlinkIfPresent(temp);
  }
}

function unlinkIfPresent(path: string): void {
  try {
    unlinkSync(path);
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error;
  }
}

function withTerminalAuthorityLock<T>(paths: ManagedHostRunPaths, fn: () => T): T {
