      command: `managed terminal ${paths.dir}`,
      acquiredAt: new Date().toISOString(),
      lockId: randomUUID(),
      processStartTimeMs: currentProcessStartTimeMs(),
    },
  });
}

function appendEvent(paths: ManagedHostRunPaths, event: ManagedHostRunEvent): boolean {
