interface MaterializedLaunch {
  command: string;
  argv: string[];
  stdinText?: string;
  promptFile?: string;
  cleanup: () => void;
}

function materializeLaunch(args: HostRunArgs): MaterializedLaunch {
  if (args.launchProfile === 'cross_host_review_codex') {
    if (args.host !== 'codex') throw new Error('host_run: cross_host_review_codex profile requires host=codex');
    return {
      command: 'codex',
      argv: ['exec', '-s', 'read-only', '-C', args.cwd, '-'],
      stdinText: args.promptText,
      cleanup: () => {},
    };
  }
  const spec = canonicalReviewHostLauncherSpec(args.host);
  if (args.host === 'claude') {
    const dir = mkdtempSync(join(tmpdir(), 'lattice-host-run-'));
    const promptFile = join(dir, 'prompt.txt');
    writeFileSync(promptFile, args.promptText, { encoding: 'utf8', mode: 0o600 });
    const full = materializeLauncherArgv(spec, { promptFile });
    return {
      command: full[0],
      argv: full.slice(1),
      promptFile,
      cleanup: () => rmSync(dir, { recursive: true, force: true }),
    };
  }
  if (args.host === 'agy') {
    throw new Error(
