async function reapProviderOnNextTouch(identity: HostRunProcessIdentity | null): Promise<boolean> {
  if (!identity?.processGroupIsolated || !identity.pgid || !identity.startFingerprint) return false;
  let rows = processGroupRows(identity.pgid);
  if (rows === null) return false;
  if (rows.length === 0) return true;
  const leader = rows.find(row => row.pid === identity.pid);
  if (!leader || leader.start !== identity.startFingerprint) return false;

  try { process.kill(-identity.pgid, 'SIGTERM'); } catch (error) {
    if ((error as NodeJS.ErrnoException).code !== 'ESRCH') return false;
  }
  await sleep(250);
  rows = processGroupRows(identity.pgid);
  if (rows === null) return false;
  if (rows.length === 0) return true;
  try { process.kill(-identity.pgid, 'SIGKILL'); } catch (error) {
    if ((error as NodeJS.ErrnoException).code !== 'ESRCH') return false;
  }
  await sleep(250);
  rows = processGroupRows(identity.pgid);
  return rows !== null && rows.length === 0;
}

async function reconcileManagedHostRun(paths: ManagedHostRunPaths, now: number): Promise<void> {
  if (readTerminal(paths)) return;
  const spec = readJson<ManagedHostRunSpec>(paths.spec);
  const snapshot = readJson<ManagedHostRunSnapshot>(paths.snapshot);
  if (now >= Date.parse(spec.deadlineAt)) {
    const request = ensureCancelRequest(paths, spec.runId, 'absolute_deadline_exceeded', now);
    // Give a healthy worker a short cooperative window. A genuinely wedged
    // worker cannot hold the status API forever: after the grace, the next touch
    // reconciles against the recorded provider identity and writes an honest
    // terminal even when replacement safety cannot be proven.
    if (now - Date.parse(request.requestedAt) < 250) return;
    const safe = snapshot.providerIdentity
      ? await reapProviderOnNextTouch(snapshot.providerIdentity)
      : snapshot.workerPid !== null && !pidAlive(snapshot.workerPid);
    writeTerminal(paths, 'timed_out', 'absolute_deadline_exceeded', safe, null, now);
    return;
  }
  const cancel = readCancelRequest(paths);
  if (cancel && now - Date.parse(cancel.requestedAt) >= 250) {
    const safe = snapshot.providerIdentity
      ? await reapProviderOnNextTouch(snapshot.providerIdentity)
      : snapshot.workerPid !== null && !pidAlive(snapshot.workerPid);
    writeTerminal(paths, 'cancelled', cancel.reason, safe, null, now);
  }
}

